 assert int(d['memory.max'])<=9663676416 and int(d['memory.swap.max'])==0 and int(d['pids.max'])<=512
 q,p=map(int,d['cpu.max'].split());assert q>0 and q<=2*p
 assert int(d['memory.current'])<8053063680 and len(d['affinity_cpus'])<=4
